  Lemma sm_dec4 : forall d0 s1 s2 out o0 s1a d1 o1 s2a d2 o2 s1b d3 o3 s2b d4 m1 (x8 x9 x18 x22 x30 x31 : word),
    decode_sym dt false s1 d0 = Ok (o0, s1a, d1) -> decode_sym dt false s2 d1 = Ok (o1, s2a, d2) ->
    decode_sym dt false s1a d2 = Ok (o2, s1b, d3) -> decode_sym dt false s2a d3 = Ok (o3, s2b, d4) ->
    0 <= bd_bits d0 <= 64 -> 0 <= bd_cont d0 < 2^64 -> zlen out + 4 <= dcap ->
    sm_inv m1 out ->
