       evt psegs POST (ST 0x1c43c m2 (Z_to_bv 64 (bd_bits d4)) (Z_to_bv 64 s2b) (Z_to_bv 64 s1b) y8 y9
                          (Z_to_bv 64 (S + bd_ptr d0)) (Z_to_bv 64 (bd_cont d0)) y18 y22 (Z_to_bv 64 (DST + zlen out + 4)) y30 y31)) ->
    evt psegs POST (ST 0x1c350 m1 (Z_to_bv 64 (bd_bits d0)) (Z_to_bv 64 s2) (Z_to_bv 64 s1) x8 x9
                       (Z_to_bv 64 (S + bd_ptr d0)) (Z_to_bv 64 (bd_cont d0)) x18 x22 (Z_to_bv 64 (DST + zlen out)) x30 x31).
