  Definition sm_okr (x : dec) : Prop :=
    bitd_ok bs (de_bd x) /\ bd_bits (de_bd x) <= 2^29 /\ zlen (de_out x) <= dcap /\ Forall (fun c => 0 <= c < 256) (de_out x).

  Notation HEADST x mm x8 x9 x18 x22 x30 x31 :=
    (ST 0x1c2ac mm (Z_to_bv 64 (bd_bits (de_bd x))) (Z_to_bv 64 (de_s2 x)) (Z_to_bv 64 (de_s1 x)) x8 x9
        (Z_to_bv 64 (S + bd_ptr (de_bd x))) (Z_to_bv 64 (bd_cont (de_bd x))) x18 x22
        (Z_to_bv 64 (DST + zlen (de_out x))) x30 x31).
  Notation EXITST r mm y8 y9 y18 y22 y30 y31 :=
    (ST 0x1c444 mm (Z_to_bv 64 (bd_bits (de_bd r))) (Z_to_bv 64 (de_s2 r)) (Z_to_bv 64 (de_s1 r)) y8 y9
        (Z_to_bv 64 (bd_reg S (de_bd r))) (Z_to_bv 64 (bd_cont (de_bd r))) y18 y22
        (Z_to_bv 64 (DST + zlen (de_out r))) y30 y31).

  Definition sm_K (r : dec) : Prop :=
    forall m2 (y8 y9 y18 y22 y30 y31 : word), sm_okr r -> sm_inv m2 (de_out r) ->
      evt psegs POST (EXITST r m2 y8 y9 y18 y22 y30 y31).

  Lemma sm_after : forall f out s1 s2 d st c b p r m1 (x8 x9 x18 x22 x30 x31 : word),
    (forall x' r' m1' (x8' x9' x18' x22' x30' x31' : word),
       main_loop bs dt dcap false f x' = Ok r' -> sm_ok x' -> sm_inv m1' (de_out x') -> sm_K r' ->
       evt psegs POST (HEADST x' m1' x8' x9' x18' x22' x30' x31')) ->
    ml_body f (mkDec out s1 s2 d) st (mkBD c b p false) = Ok r ->
    bitd_ok bs (mkBD c b p false) -> b <= 64 -> zlen out <= dcap -> Forall (fun c => 0 <= c < 256) out ->
    dstatus_eqb st Unfinished = negb (bv_unsigned x30 =? 0) ->
    sm_inv m1 out -> sm_K r ->
    evt psegs POST (ST 0x1c348 m1 (Z_to_bv 64 b) (Z_to_bv 64 s2) (Z_to_bv 64 s1) x8 x9 (Z_to_bv 64 (S + p)) (Z_to_bv 64 c)
                       x18 x22 (Z_to_bv 64 (DST + zlen out)) x30 x31).
Proof.
